local _, A = ...
-- World reference material only. Quest outcomes describe the source story;
-- these notes do not assert that the reader accepted or completed that quest.
local V = "StorageInvestigation/journal-voice/review/corpus_vanilla_quests.txt"
local function Q(ids)
    local out = {}
    for _, id in ipairs(ids) do out[#out + 1] = V .. " (quest " .. id .. ")" end
    return out
end
local function N(id, title, kind, body, ids, names, related)
    return {id = id, title = title, kind = kind, body = body, sources = Q(ids), names = names, related = related, autoLink = kind == "Person" and not title:find("%s") or nil}
end
local function W(id, title, kind, body, url, names, related)
    return {id = id, title = title, kind = kind, body = body, sources = {url}, names = names, related = related, autoLink = kind == "Person" and not title:find("%s") or nil}
end
